<script lang="ts">
 import ExpandableValue from '../components/ExpandableValue.svelte';
 import AppSelect from '../components/Select.svelte';import {untrack} from 'svelte';import Icon from '../components/Icon.svelte';import {demo,saveRow,getRow,runAction,toast,download,errorMessage} from '../store.svelte';import YAML from 'yaml';
 let {kind}=$props<{kind:'routing'|'templates'}>();let tab=$state(untrack(()=>kind==='routing'?'路由规则':'规则覆写')),serverId=$state(''),name=$state(''),recordId=$state(''),text=$state(''),version=$state('3'),valid=$state('尚未校验'),busy=$state(false),preview=$state(''),templateId=$state(''),ruleType=$state('rules'),ruleMode=$state('prepend'),versions=$state<any[]>([]),importURL=$state('');
 const tabs=$derived(kind==='routing'?['路由规则','DNS']:['规则覆写','脚本覆写']);const isTemplate=$derived(kind==='templates'&&tab==='客户端模板');const isScript=$derived(tab==='脚本覆写');
 function changeTab(t:string){tab=t;recordId='';text='';name='';valid='尚未校验';preview='';versions=[];}
 async function load(id:string){busy=true;try{const record=await getRow(isTemplate?'policies':'rules',id);recordId=id;name=record.name;text=record.script??record.content??'';templateId=record.templateId??'';ruleType=record.type??'rules';ruleMode=record.mode??'prepend';if(isTemplate){const result=await runAction('template.history',id);versions=result.versions??[];}}catch(cause){valid=errorMessage(cause);}finally{busy=false;}}
 function loadServer(id:string){serverId=id;const server=demo.data.servers.find(s=>s.id===id);text=JSON.stringify(server?.globalConfig?.[tab==='DNS'?'dns':'routing']??{},null,2);valid='尚未校验';}
 async function validate(){busy=true;try{if(isScript){await runAction('script.validate',undefined,undefined,{script:text});}else if(isTemplate){const result=await runAction('template.preview',undefined,undefined,{content:text,version:Number(version),url:importURL});preview=result.preview??'';valid=(result.warnings??[]).join('；')||'主控校验通过';return true;}else{const value=kind==='routing'?JSON.parse(text):YAML.parse(text);if(!value||Array.isArray(value)||typeof value!=='object')throw new Error('配置须为对象');}valid='语法校验通过';return true;}catch(cause){valid='校验失败：'+errorMessage(cause);return false;}finally{busy=false;}}
 async function save(apply=false){if(busy)return;if(!await validate())return;busy=true;try{if(kind==='routing'){if(!serverId)throw new Error('请选择服务器');await runAction('server.global.update',serverId,'servers',{section:tab==='DNS'?'dns':'routing',config:JSON.parse(text),apply});toast(apply?'配置发布已提交，请查看任务结果':'全局配置已保存');}else if(isTemplate){if(!name.trim())throw new Error('请填写模板名称');const result=await runAction('template.import',recordId||undefined,'policies',{name,content:text,version:Number(version),url:importURL});recordId=result.row.id;text=result.content;version='3';preview=result.preview;importURL='';toast('模板已保存，绑定此模板的订阅将在下次生成时使用');}else{if(!name.trim())throw new Error('请填写规则名称');const record=await saveRow('rules',{id:recordId||crypto.randomUUID(),name,type:isScript?'script':ruleType,mode:ruleMode,templateId,content:text,...(isScript?{script:text}:{}),status:'启用'});recordId=record.id;toast('规则已保存');}}catch(cause){valid='保存失败：'+errorMessage(cause);}finally{busy=false;}}
 async function restore(id:string){busy=true;try{const result=await runAction('template.restore',recordId,'policies',{versionId:id});text=result.row.content;toast('模板版本已恢复');}catch(cause){valid=errorMessage(cause);}finally{busy=false;}}
</script>
<div class="page-head"><div><div class="eyebrow">工作区 / 配置</div><h1>{kind==='routing'?'路由与 DNS':'规则与脚本'}</h1><p>{kind==='routing'?'按服务器保存路由与 DNS，再交由 Agent 检查应用。':'保存客户端模板与覆写规则，绑定到指定套餐实例。'}</p></div><div class="actions"><button class="button" disabled={busy} onclick={()=>save()}>保存配置</button>{#if kind==='routing'}<button class="button primary" disabled={busy||!serverId} onclick={()=>save(true)}><Icon name="play"/>发布配置</button>{/if}</div></div>
<div class="tabs">{#each tabs as t}<button class:active={tab===t} onclick={()=>{changeTab(t);if(kind==='routing')loadServer(serverId);}}>{t}</button>{/each}</div><div class="split"><section class="card padded"><h2>{tab}</h2><div class="form-grid space-top">{#if kind==='routing'}<label class="field full">服务器<AppSelect value={serverId} onchange={loadServer} options={[{value:'',label:'选择服务器'},...demo.data.servers.map(s=>({value:s.id,label:s.name}))]} aria-label="配置服务器"/></label>{:else}<label class="field full">名称<input bind:value={name}/></label>{#if isTemplate}<label class="field">输入模板版本<AppSelect bind:value={version} options={['1','2','3']} aria-label="模板版本"/></label><label class="field">远程模板 URL（可选）<input type="url" bind:value={importURL}/></label>{:else if !isScript}<label class="field">覆写类型<AppSelect bind:value={ruleType} options={[{value:'rules',label:'路由规则'},{value:'dns',label:'DNS'},{value:'rule-providers',label:'规则集'}]} aria-label="覆写类型"/></label><label class="field">覆写方式<AppSelect bind:value={ruleMode} options={[{value:'prepend',label:'前置'},{value:'append',label:'追加'},{value:'replace',label:'替换'}]} aria-label="覆写方式"/></label><label class="field full">限定模板<AppSelect bind:value={templateId} options={[{value:'',label:'所有模板'},...demo.data.policies.map(p=>({value:p.id,label:p.name}))]} aria-label="限定模板"/></label>{/if}{/if}</div><label class="field space-top"><span>{isScript?'JavaScript':kind==='routing'?'JSON':version==='2'&&isTemplate?'INI':'YAML / JSON'} 配置</span><textarea class="code-editor" aria-label="配置编辑器" spellcheck="false" bind:value={text} oninput={()=>valid='尚未校验'}></textarea></label><div class="section-head space-top"><span class:error={valid.includes('失败')} class="hint" role="status">{valid}</span><button class="button small" disabled={busy} onclick={validate}><Icon name="check"/>校验</button></div>{#if preview}<h3 class="space-top">主控预览</h3>{#key recordId}{#key preview}<ExpandableValue value={preview} label="预览配置详情" force />{/key}{/key}{/if}</section><aside class="stack"><section class="card padded"><h2>{kind==='routing'?'应用范围':'已保存配置'}</h2>{#if kind==='routing'}<p class="muted space-top">仅更新所选服务器的{tab}部分。发布会生成配置，并由 Agent 校验后重启核心。</p><a href="/servers" class="quiet-link space-top">读取或编辑 Agent 完整配置</a>{:else}{#each (isTemplate?demo.data.policies:(demo.data.rules??[]).filter(r=>isScript?r.type==='script':r.type!=='script')) as record}<div class="car-summary"><strong>{record.name}</strong><button class="button small" disabled={busy} onclick={()=>load(record.id)}>编辑</button></div>{:else}<p class="empty">尚无保存的配置</p>{/each}<p class="hint">模板和脚本在订阅实例的编辑页面绑定。规则覆写按指定模板生效；留空时作用于全部实例。</p><a href="/subscriptions" class="quiet-link">绑定到套餐实例</a>{/if}</section>{#if isTemplate&&versions.length}<section class="card padded"><h2>模板历史</h2>{#each versions as v}<div class="car-summary"><small>{v.createdAt}</small><button class="button small" disabled={busy} onclick={()=>restore(v.id)}>恢复</button></div>{/each}</section>{/if}<section class="card padded"><h2>本次编辑</h2><p class="muted space-top">{text.split('\n').length} 行 · {new TextEncoder().encode(text).length} 字节</p><button class="button space-top" onclick={()=>download(isScript?'aswired-script.js':'aswired-policy.txt',text)}>导出</button>{#if isScript}<p class="hint">入口函数为 main(config)，应返回完整配置。脚本无法访问网络或文件，执行上限由主控约束。</p>{/if}</section></aside></div>
